function generateRoleInput($fieldId, $fieldName, $currentValue, $placeholder, $useManualIds, $guildRoles, $icon = 'fas fa-user-tag', $required = false)
{
  $requiredAttr = $required ? ' required' : '';
  if ($useManualIds || empty($guildRoles)) {
